import{_ as r,a0 as i,w as l,s as m,ao as s,I as a,a1 as n,A as o,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse(`{"title":"在 LVM中 錄製邏輯卷快照並恢復（第三部分） | LCTT x X-CMD","titleTemplate":false,"description":"在 LVM中 錄製邏輯卷快照並恢復（第三部分） | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 LVM中 錄製邏輯卷快照並恢復（第三部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 LVM中 錄製邏輯卷快照並恢復（第三部分） | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140818 How to Take 'Snapshot of Logical Volume and Restore' in LVM--Part III","title":"在 LVM中 錄製邏輯卷快照並恢復（第三部分）","tag":"201411","desc":""},"relativePath":"201411/20140818 How to Take 'Snapshot of Logical Volume and Restore' in LVM--Part III.md","filePath":"[post].md"}`),c={name:"201411/20140818 How to Take 'Snapshot of Logical Volume and Restore' in LVM--Part III.md"};function d(g,t,h,w,u,L){const p=i("Link");return l(),m("div",null,[t[15]||(t[15]=s('<h1 id="在-lvm中-錄製邏輯卷快照並恢復-第三部分" tabindex="-1">在 LVM中 錄製邏輯卷快照並恢復（第三部分） <a class="header-anchor" href="#在-lvm中-錄製邏輯卷快照並恢復-第三部分" aria-label="Permalink to “在 LVM中 錄製邏輯卷快照並恢復（第三部分）”">​</a></h1><p><strong>LVM快照</strong>是以空間換時間時間的方式製作的lvm卷副本。它只在lvm中工作，並只在源邏輯捲髮生改變時佔用快照卷的空間。如果源卷的變化達到1GB這麼大，快照卷同樣也會產生這樣大的改變。因而，對於空間有效利用的最佳途徑，就是總是進行小的修改。如果快照將存儲空間消耗殆盡，我們可以使用lvextend來擴容。而如果我們需要縮減快照所佔用卷的大小，可以使用lvreduce。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Take-Snapshot-in-LVM.jpg" alt="Take Snapshot in LVM"></p><p><em>在LVM中錄製快照</em></p><p>如果我們在創建快照後意外地刪除了無論什麼文件，我們沒有必要擔心，因為快照裏包含了我們所刪除的文件的原始文件。創建快照時，很有可能文件已經存在了。不要改變快照卷，保持創建時的樣子，因為它用於快速恢復。</p><p>快照不可以用於備份選項。備份是某些數據的基礎副本，因此我們不能使用快照作為備份的一個選擇。</p><h4 id="前置閲讀" tabindex="-1">前置閲讀 <a class="header-anchor" href="#前置閲讀" aria-label="Permalink to “前置閲讀”">​</a></h4>',7)),a("ul",null,[a("li",null,[n(p,{href:"http://linux.cn/article-3965-1.html"},{default:o(()=>[...t[0]||(t[0]=[e("在Linux中使用LVM構建靈活的磁盤存儲（第一部分）",-1)])]),_:1})]),a("li",null,[n(p,{href:"http://linux.cn/article-3974-1.html"},{default:o(()=>[...t[1]||(t[1]=[e("在Linux中擴展/縮減LVM（第二部分）",-1)])]),_:1})])]),t[16]||(t[16]=s(`<h3 id="我的服務器設置" tabindex="-1">我的服務器設置 <a class="header-anchor" href="#我的服務器設置" aria-label="Permalink to “我的服務器設置”">​</a></h3><ul><li>操作系統 — 安裝有LVM的CentOS 6.5</li><li>服務器IP — 192.168.0.200</li></ul><h4 id="步驟1-創建lvm快照" tabindex="-1">步驟1： 創建LVM快照 <a class="header-anchor" href="#步驟1-創建lvm快照" aria-label="Permalink to “步驟1： 創建LVM快照”">​</a></h4><p>首先，使用‘<strong>vgs</strong>’命令檢查卷組中的空閒空間以創建新的快照。</p><pre><code># vgs
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-LVM-Disk-Space.jpg" alt="Check LVM Disk Space"></p><p><em>檢查LVM磁盤空間</em></p><p>正如你所見，在<strong>vgs</strong>命令輸出中，我們可以看到有8GB的剩餘空閒空間。所以，讓我們為我的名為<strong>tecmint_datas</strong>的卷創建快照。處於演示的目的，我將會使用以下命令來創建1GB的快照卷。</p><pre><code># lvcreate -L 1GB -s -n tecmint_datas_snap /dev/vg_tecmint_extra/tecmint_datas        
</code></pre><p>或者</p><pre><code># lvcreate --size 1G --snapshot --name tecmint_datas_snap /dev/vg_tecmint_extra/tecmint_datas
</code></pre><p>上面的兩個命令都是幹得同一件事：</p><ul><li><strong>-s</strong> – 創建快照</li><li><strong>-n</strong> – 為快照命名</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Create-LVM-Snapshot.jpg" alt="Create LVM Snapshot"></p><p><em>創建LVM快照</em></p><p>此處，是對上面高亮要點的説明。</p><ol><li>我在此創建的快照的大小。</li><li>創建快照。</li><li>創建快照名。</li><li>新的快照名。</li><li>要創建快照的卷。</li></ol><p>如果你想要移除快照，可以使用‘<strong>lvremove</strong>’命令。</p><pre><code># lvremove /dev/vg_tecmint_extra/tecmint_datas_snap
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Remove-LVM-Snapshot.jpg" alt="Remove LVM Snapshot"></p><p><em>移除LVM快照</em></p><p>現在，使用以下命令列出新創建的快照。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Verify-LVM-Snapshot.jpg" alt="Verify LVM Snapshot"></p><p><em>驗證LVM快照</em></p><p>上面的你看到了吧，成功創建了一個快照。上面我用箭頭標出了快照創建的源，它就是<strong>tecmint_datas</strong>。是的，因為我已經為<strong>tecmint_datas l-volume</strong>創建了一個快照。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-LVM-Snapshot-Space.jpg" alt="Check LVM Snapshot Space"></p><p><em>檢查LVM快照空間</em></p><p>讓我們添加一些新文件到<strong>tecmint_datas</strong>裏頭。現在卷裏大概有650MB左右的數據，而我我們的快照有1GB大。因此，有足夠的空間在快照卷裏備份我們的修改。這裏我們可以使用下面的命令來查看到，我們的快照當前的狀態。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Snapshot-Status.jpg" alt="Check Snapshot Status"></p><p><em>檢查快照狀態</em></p><p>你看到了，現在已經用掉了<strong>51%</strong>的快照卷，你要對你的文件作更多的修改都沒有問題。使用下面的命令來查看更多詳細信息。</p><pre><code># lvdisplay vg_tecmint_extra/tecmint_data_snap
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Snapshot-Information.jpg" alt="View Snapshot Information"></p><p><em>查看快照信息</em></p><p>再來對上面圖片中高亮的要點作個清楚的説明。</p><ol><li>快照邏輯卷名稱。</li><li>當前使用的卷組名。</li><li>讀寫模式下的快照卷，我們甚至可以掛載並使用該卷。</li><li>快照創建時間。這個很重要，因為快照將跟蹤此時間之後的每個改變。</li><li>該快照屬於tecmint_datas邏輯卷。</li><li>邏輯卷在線並可用。</li><li>我們錄製快照的源卷大小。</li><li>寫時複製表大小，Cow = copy on Write，這是説對tecmint_data卷所作的任何改變都會寫入此快照。</li><li>當前使用的快照大小，我們的tecmint_data有10GB，而我們的快照大小是1GB，這就意味着我們的數據大概有650MB。所以，如果tecmint_datas中的文件增長到2GB，現在的51%中的內容將增加到超過所分配的快照的大小，當然，我們在創建快照時會出現問題。這就意味着我們需要擴展邏輯卷大小（快照邏輯卷）</li><li>給出快照組塊的大小。</li></ol><p>現在，讓我們複製超過1GB的文件到<strong>tecmint_datas</strong>。讓我們看看會發生什麼。如果你那麼做了，你將會見到‘<strong>Input/output error</strong>’這樣的錯誤信息，它告訴你快照超出空間大小了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Add-Files-to-Snapshot.jpg" alt="Add Files to Snapshot"></p><p><em>添加文件到快照</em></p><p>如果該邏輯卷滿了，它就會自動丟失新的數據，我們就不能再使用了，就算我們去擴展快照卷的大小也不行。最好的方法就是在創建快照時，創建一個和源一樣大小的快照卷。<strong>tecmint_datas</strong>的大小是10GB，如果我們創建一個10GB大小的快照，它就永遠都不會像上面那樣超載，因為它有足夠的空間來錄製你的邏輯卷的快照。</p><h4 id="步驟2-在lvm中擴展快照" tabindex="-1">步驟2： 在LVM中擴展快照 <a class="header-anchor" href="#步驟2-在lvm中擴展快照" aria-label="Permalink to “步驟2： 在LVM中擴展快照”">​</a></h4><p>如果我們需要在超過容量前擴展快照卷的大小，我們可以使用以下命令來完成此項任務。</p><pre><code># lvextend -L +1G /dev/vg_tecmint_extra/tecmint_data_snap
</code></pre><p>現在，那裏有總計2GB大小的快照空間。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Extend-LVM-Snapshot.jpg" alt="Extend LVM Snapshot"></p><p><em>擴展LVM快照</em></p><p>接下來，使用以下命令來驗證新的大小和寫時複製表。</p><pre><code># lvdisplay /dev/vg_tecmint_extra/tecmint_data_snap
</code></pre><p>要知道快照卷的大小使用<strong>%</strong>。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Size-of-Snapshot.jpg" alt="Check Size of Snapshot"></p><p><em>檢查快照大小</em></p><p>然而，如果你的快照大小和源卷一樣，我們就沒有必要擔心這些問題了。</p><h4 id="步驟3-恢復快照或合併" tabindex="-1">步驟3： 恢復快照或合併 <a class="header-anchor" href="#步驟3-恢復快照或合併" aria-label="Permalink to “步驟3： 恢復快照或合併”">​</a></h4><p>要恢復快照，我們首先需要卸載文件系統。</p><pre><code># unmount /mnt/tecmint_datas/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Unmount-File-System.jpg" alt="Un-mount File System"></p><p><em>卸載文件系統</em></p><p>只想檢查掛載點是否卸載成功，可以使用下面的命令。</p><pre><code># df -h
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Mount-Points.jpg" alt="Check File System Mount Points"></p><p><em>檢查文件系統掛載點</em></p><p>這裏，我們的掛載已經被卸載，所以我們可以繼續恢復快照。要恢復快照，可以使用<strong>lvconvert</strong>命令。</p><pre><code># lvconvert --merge /dev/vg_tecmint_extra/tecmint_data_snap
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Restore-Snapshot.jpg" alt="Restore LVM Snapshot"></p><p><em>恢復LVM快照</em></p><p>在合併完成後，快照卷將被自動移除。現在我們可以使用<strong>df</strong>命令來查看分區大小。</p><pre><code># df -Th
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Snapshot-Space.jpg" alt="Check Size of Snapshot"></p><p>在快照卷自動移除後，你可以用下面的命令查看邏輯卷大小。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/Check-Size-of-LV.jpg" alt="Check Size of Logical Volume"></p><p><em>檢查邏輯卷大小</em></p><p><strong>重要</strong>：要自動擴展快照，我們可以通過修改配置文件來進行。對於手動擴展，我們可以使用lvextend。</p><p>使用你喜歡的編輯器打開lvm配置文件。</p><pre><code># vim /etc/lvm/lvm.conf
</code></pre><p>搜索單詞autoextend。默認情況下，該值和下圖中的類似。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/08/LVM-Configuration.jpg" alt="LVM Configuration"></p><p><em>LVM配置</em></p><p>修改此處的<strong>100</strong>為<strong>75</strong>，這樣自動擴展的起始點就是<strong>75</strong>，而自動擴展百分比為20，它將自動擴容<strong>百分之20</strong>。</p><p>如果快照卷達到<strong>75%</strong>，它會自動為快照卷擴容<strong>20%</strong>。這樣，我們可以自動擴容了。使用<strong>wq!</strong>來保存並退出。</p><p>這將把快照從超載導致下線事故中拯救出來，這也會幫助你節省更多時間。LVM是我們擴容以及獲得其它眾多特性如精簡資源調配、拆卸、虛擬卷和使用精簡池的唯一方法，讓我們在下一個話題中來討論吧。</p><hr>`,85)),a("p",null,[t[3]||(t[3]=e("via: ",-1)),n(p,{href:"http://www.tecmint.com/take-snapshot-of-logical-volume-and-restore-in-lvm/"},{default:o(()=>[...t[2]||(t[2]=[e("http://www.tecmint.com/take-snapshot-of-logical-volume-and-restore-in-lvm/",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=e("作者：",-1)),n(p,{href:"http://www.tecmint.com/author/babinlonston/"},{default:o(()=>[...t[4]||(t[4]=[e("Babin Lonston",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),n(p,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[5]||(t[5]=[e("GOLinux",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),n(p,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創翻譯，",-1)),n(p,{href:"http://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const M=r(c,[["render",d]]);export{v as __pageData,M as default};
